CREATE TABLE condominio (id_condominio BIGSERIAL PRIMARY KEY,ruc VARCHAR(13) NOT NULL UNIQUE,nombre VARCHAR(120) NOT NULL,direccion VARCHAR(200) NOT NULL,ciudad VARCHAR(60) NOT NULL,email_contacto VARCHAR(120) NOT NULL,dia_vencimiento SMALLINT NOT NULL DEFAULT 5 CHECK(dia_vencimiento BETWEEN 1 AND 28),tasa_mora_anual NUMERIC(5,2) NOT NULL DEFAULT 0,periodo_cerrado_hasta DATE,estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO' CHECK(estado IN ('ACTIVO','INACTIVO')));
CREATE TABLE unidad (id_unidad BIGSERIAL PRIMARY KEY,id_condominio BIGINT NOT NULL REFERENCES condominio,bloque VARCHAR(20),codigo VARCHAR(15) NOT NULL,tipo_unidad VARCHAR(15) NOT NULL DEFAULT 'DEPARTAMENTO',piso SMALLINT,area_m2 NUMERIC(8,2),estado_ocupacion VARCHAR(15) NOT NULL DEFAULT 'OCUPADA',clave_catastral VARCHAR(30),estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO',UNIQUE(id_condominio,codigo));
CREATE TABLE persona (id_persona BIGSERIAL PRIMARY KEY,tipo_identificacion VARCHAR(12) NOT NULL,numero_identificacion VARCHAR(20) NOT NULL UNIQUE,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,email VARCHAR(120),telefono VARCHAR(20),fecha_nacimiento DATE,direccion VARCHAR(200),estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO');
CREATE TABLE cuenta_contable (id_cuenta_contable BIGSERIAL PRIMARY KEY,codigo VARCHAR(20) NOT NULL UNIQUE,nombre VARCHAR(100) NOT NULL,tipo VARCHAR(12) NOT NULL,numero_cuenta VARCHAR(30),banco VARCHAR(60),estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO');
CREATE TABLE residente (id_residente BIGSERIAL PRIMARY KEY,id_unidad BIGINT NOT NULL REFERENCES unidad,id_persona BIGINT NOT NULL REFERENCES persona,tipo_relacion VARCHAR(15) NOT NULL,es_responsable_pago BOOLEAN NOT NULL DEFAULT FALSE,porcentaje_propiedad NUMERIC(5,2),recibe_notificaciones BOOLEAN NOT NULL DEFAULT TRUE,fecha_inicio DATE NOT NULL DEFAULT CURRENT_DATE,fecha_fin DATE,estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO');
CREATE TABLE alicuota (id_alicuota BIGSERIAL PRIMARY KEY,id_unidad BIGINT NOT NULL REFERENCES unidad,porcentaje NUMERIC(9,6) NOT NULL,cuota_ordinaria NUMERIC(12,2) NOT NULL,vigente_desde DATE NOT NULL,vigente_hasta DATE,resolucion_asamblea VARCHAR(60),motivo_cambio VARCHAR(150),estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO');
CREATE TABLE rubro_adicional (id_rubro BIGSERIAL PRIMARY KEY,id_condominio BIGINT NOT NULL REFERENCES condominio,id_cuenta_contable BIGINT REFERENCES cuenta_contable,codigo VARCHAR(10) NOT NULL,nombre VARCHAR(80) NOT NULL,tipo_calculo VARCHAR(12) NOT NULL,valor_defecto NUMERIC(12,2) NOT NULL,periodicidad VARCHAR(12) NOT NULL,es_obligatorio BOOLEAN NOT NULL DEFAULT FALSE,estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO',UNIQUE(id_condominio,codigo));
CREATE TABLE detalle_alicuota (id_detalle_alicuota BIGSERIAL PRIMARY KEY,id_alicuota BIGINT NOT NULL REFERENCES alicuota,id_rubro BIGINT NOT NULL REFERENCES rubro_adicional,cantidad NUMERIC(10,2) NOT NULL DEFAULT 1,valor_asignado NUMERIC(12,2) NOT NULL,vigente_desde DATE NOT NULL,vigente_hasta DATE,observacion VARCHAR(150),estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO');
CREATE TABLE cargo (id_cargo BIGSERIAL PRIMARY KEY,id_unidad BIGINT NOT NULL REFERENCES unidad,id_persona BIGINT NOT NULL REFERENCES persona,anio SMALLINT NOT NULL,mes SMALLINT NOT NULL CHECK(mes BETWEEN 1 AND 12),numero_cargo VARCHAR(20) NOT NULL UNIQUE,fecha_vencimiento DATE NOT NULL,total NUMERIC(12,2) NOT NULL,saldo NUMERIC(12,2) NOT NULL,estado VARCHAR(12) NOT NULL CHECK(estado IN ('PENDIENTE','PARCIAL','PAGADO','ANULADO')),UNIQUE(id_unidad,anio,mes));
CREATE TABLE detalle_cargo (id_detalle_cargo BIGSERIAL PRIMARY KEY,id_cargo BIGINT NOT NULL REFERENCES cargo ON DELETE CASCADE,id_alicuota BIGINT REFERENCES alicuota,id_rubro BIGINT REFERENCES rubro_adicional,tipo_concepto VARCHAR(12) NOT NULL,descripcion VARCHAR(150) NOT NULL,cantidad NUMERIC(10,2) NOT NULL,valor_unitario NUMERIC(12,2) NOT NULL,subtotal NUMERIC(12,2) NOT NULL);
CREATE TABLE pago (id_pago BIGSERIAL PRIMARY KEY,id_unidad BIGINT REFERENCES unidad,id_persona BIGINT NOT NULL REFERENCES persona,id_cuenta_destino BIGINT REFERENCES cuenta_contable,id_cuenta_ingreso BIGINT REFERENCES cuenta_contable,fecha_pago DATE NOT NULL,monto NUMERIC(14,2) NOT NULL CHECK(monto>0),forma_pago VARCHAR(15) NOT NULL,referencia VARCHAR(40),estado VARCHAR(12) NOT NULL DEFAULT 'REGISTRADO');
CREATE TABLE aplicacion_pago (id_aplicacion BIGSERIAL PRIMARY KEY,id_pago BIGINT NOT NULL REFERENCES pago,id_cargo BIGINT REFERENCES cargo,id_cuota_acuerdo BIGINT,tipo_aplicacion VARCHAR(15) NOT NULL,monto_aplicado NUMERIC(14,2) NOT NULL,fecha_aplicacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO',observacion VARCHAR(150),CHECK(id_cargo IS NOT NULL OR tipo_aplicacion='ANTICIPO'));
CREATE TABLE comprobante (id_comprobante BIGSERIAL PRIMARY KEY,tipo VARCHAR(8) NOT NULL,numero VARCHAR(25) NOT NULL UNIQUE,fecha_emision DATE NOT NULL,id_pago BIGINT REFERENCES pago,id_gasto BIGINT,id_cuenta_contable BIGINT,referencia VARCHAR(40),valor_total NUMERIC(14,2) NOT NULL,estado VARCHAR(12) NOT NULL DEFAULT 'EMITIDO',CHECK((tipo='INGRESO' AND id_pago IS NOT NULL AND id_gasto IS NULL) OR (tipo='EGRESO' AND id_gasto IS NOT NULL AND id_pago IS NULL)));
CREATE TABLE rol (id_rol BIGSERIAL PRIMARY KEY,nombre VARCHAR(30) NOT NULL UNIQUE,descripcion VARCHAR(120),permisos JSONB NOT NULL DEFAULT '[]',estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO');
CREATE TABLE usuario (id_usuario BIGSERIAL PRIMARY KEY,id_persona BIGINT REFERENCES persona,id_rol BIGINT NOT NULL REFERENCES rol,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,intentos_fallidos SMALLINT NOT NULL DEFAULT 0,bloqueado_hasta TIMESTAMP,estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVO');
